def count_sequences(n: int, last: int, memo: dict) -> int:
    if (n, last) in memo:
        return memo[(n, last)]

    # Base case: if next number is the largest possible, there's exactly one way
    if n == last:
        return 1

    # Recursive case: count sequences supporting the new number
    total_sequences = 0
    for next_num in range(1, (last // 2) + 1):
        total_sequences += count_sequences(n, next_num, memo)

    # Memoize the result
    memo[(n, last)] = total_sequences
    return total_sequences

