def catalan_number(n: int) -> int:
    # Base case: C(0) is 1
    if n == 0:
        return 1

    # Initialize an array to store Catalan numbers
    catalan = [0] * (n + 1)
    catalan[0] = 1

    # Calculate the Catalan numbers using the recursive formula
    for i in range(1, n + 1):
